def longest(s):
    stack, best = [-1], 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

def longest_dp(s):
    n, best, dp = len(s), 0, [0] * (len(s) + 1)
    for i in range(1, n + 1):
        if s[i-1] == ')':
            if s[i-2] == '(':
                dp[i] = (dp[i-2] if i >= 2 else 0) + 2
            elif i - dp[i-1] - 2 >= 0 and s[i - dp[i-1] - 2] == '(':
                dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 3] if i - dp[i-1] - 3 >= 0 else 0)
            best = max(best, dp[i])
    return best

