def longestValidParentheses(s: str) -> int:
    stack = [-1]           # 哨兵：最早边界的前一位
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:          # 空栈：前面全废，重置基准
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

