def longestValidParentheses(s: str) -> int:
    n = len(s)
    dp = [0] * n           # dp[i]：以 i 结尾的最长有效长度
    best = 0
    for i in range(1, n):
        if s[i] != ')':
            continue
        if s[i - 1] == '(':
            dp[i] = (dp[i - 2] if i >= 2 else 0) + 2
        elif i - dp[i - 1] - 1 >= 0 and s[i - dp[i - 1] - 1] == '(':
            dp[i] = dp[i - 1] + 2 + (dp[i - dp[i - 1] - 2] if i - dp[i - 1] - 2 >= 0 else 0)
        best = max(best, dp[i])
    return best

