def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    a, b = 1, 2          # f(1), f(2)
    for _ in range(3, n + 1):
        a, b = b, a + b  # 滚动数组，O(1) 空间
    return b

solution.python:
def climbStairs(n: int) -> int:
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1], dp[2] = 1, 2
    for k in range(3, n + 1):
        dp[k] = dp[k - 1] + dp[k - 2]
    return dp[n]

